p as (
  select c.id, avg(g.lat) lat, avg(g.lng) lng, count(*) n
    from c join (select distinct on (region_name, complex_name) region_name, complex_name, lat, lng from complex_geocode where status='ok' and lat is not null) g
      on replace(g.region_name,' ','') = c.rk and g.complex_name = c.cn
   group by c.id)
insert into public.redevelopment_projects(id,name,type_key,stage_key,sido,sigungu,address,lat,lng,households,summary,source,source_url,is_sample,updated_at)
select m.id, m.name, m.type_key, 'designated', m.sido, m.sigungu, m.sigungu || ' · 단지 ' || p.n || '곳 좌표 평균',
       round(p.lat::numeric,7)::float8, round(p.lng::numeric,7)::float8, m.households, m.summary, m.source, m.source_url, false, now()
  from m join p using (id)
on conflict (id) do update set name=excluded.name, type_key=excluded.type_key, stage_key=excluded.stage_key, sido=excluded.sido, sigungu=excluded.sigungu,
  address=excluded.address, lat=excluded.lat, lng=excluded.lng, households=excluded.households, summary=excluded.summary,
  source=excluded.source, source_url=excluded.source_url, updated_at=now();

select type_key, count(*) from public.redevelopment_projects where id like 'nt-%' group by 1;
